    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.path = os.path.join(self._tmp.name, "wrr.db")

    def tearDown(self):
        self._tmp.cleanup()

    def guard(self, **kwargs):
        return WideRangeReplayGuard(**kwargs)

